const labels={library:"My Reading Library",smartAudio:"Smart Audio Reader",general:"General",appearance:"Appearance & Themes",toolbar:"Toolbars",websites:"Supported Websites",reading:"Reading Preferences",highlight:"Highlight Preferences",tts:"Text-to-Speech",vocabulary:"Vocabulary",ai:"AI Configuration",notifications:"Notifications",storage:"Storage & Backup",privacy:"Privacy & Permissions",medium:"Medium Compatibility",intelligence:"Knowledge Intelligence",topics:"Topics & Knowledge",productivity:"Productivity Centre",performance:"Performance",database:"Database Manager",sync:"GitHub Data Sync"};
function inputFor([label,key,type,opts,min,max]){
 const val=data.settings[key] ?? (type==="check"?false:type==="range"?(min+max)/2:"");
 if(type==="check")return `<input type="checkbox" data-key="${key}" ${val?"checked":""}>`;
 if(type==="select")return `<select data-key="${key}">${opts.map(v=>`<option ${v===val?"selected":""} value="${v}">${v}</option>`).join("")}</select>`;
 if(type==="range")return `<input type="range" data-key="${key}" min="${min}" max="${max}" step="${(max-min)>10?1:.1}" value="${val}"><output>${val}</output>`;
 return `<input type="${type==="color"?"color":type==="password"?"password":"text"}" data-key="${key}" value="${String(val).replace(/"/g,"&quot;")}">`;
}
function row(item){return `<div class="setting"><div><strong>${item[0]}</strong><small>${helpText(item[1])}</small></div>${inputFor(item)}</div>`;}
function helpText(key){return ({aiConsent:"External services receive article text only after you enable this option.",aiKey:"Stored locally in Chrome extension storage. Do not share your profile.",mediumAlerts:"Reminders only; the extension cannot reset server-enforced reading quotas.",readingWidth:"Controls the preferred content width in the reader workspace."})[key]||"Saved locally in this browser.";}

function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function downloadJson(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeJson(value){try{JSON.parse(value);return true;}catch{return false;}}
function makeManifest(d){return ['articles','highlights','notes','vocabulary','bookmarks','collections','topics','readingHistory'].map(k=>({path:`${k}/`,count:(d[k]||[]).length}));}

async function readAdapterZip(file){
 const buf=new Uint8Array(await file.arrayBuffer());
 const view=new DataView(buf.buffer);
 const sig=0x06054b50; let eocd=-1;
 for(let i=buf.length-22;i>=Math.max(0,buf.length-65557);i--){if(view.getUint32(i,true)===sig){eocd=i;break;}}
 if(eocd<0) throw Error('Not a valid ZIP archive.');
 const count=view.getUint16(eocd+10,true), cdSize=view.getUint32(eocd+12,true), cdOffset=view.getUint32(eocd+16,true);
 const maxFiles=Number(data.settings?.adapterMaxFiles||500), maxPackageMB=Number(data.settings?.adapterMaxPackageMB||25); if(count>maxFiles||cdOffset+cdSize>buf.length) throw Error('ZIP directory is invalid or too large.');
 if(buf.byteLength>maxPackageMB*1024*1024) throw Error(`Adapter ZIP exceeds the ${maxPackageMB} MB package limit.`);
 let pos=cdOffset, files=[], seen=new Set(), totalUncompressed=0;
 for(let n=0;n<count;n++){if(view.getUint32(pos,true)!==0x02014b50) throw Error('Invalid ZIP central directory.'); const method=view.getUint16(pos+10,true), compSize=view.getUint32(pos+20,true), uncomp=view.getUint32(pos+24,true), nameLen=view.getUint16(pos+28,true), extraLen=view.getUint16(pos+30,true), commentLen=view.getUint16(pos+32,true), localOffset=view.getUint32(pos+42,true); const name=new TextDecoder().decode(buf.slice(pos+46,pos+46+nameLen)); if(!name||name.includes('..')||name.startsWith('/')||name.includes('\\')||/^[A-Za-z]:[\\/]/.test(name)) throw Error('Unsafe ZIP path: '+name); if(/\.(exe|dll|com|scr|bat|cmd|msi|ps1|sh|vbs|jar|wasm)$/i.test(name)) throw Error('Prohibited executable file: '+name); if(compSize>10*1024*1024||uncomp>20*1024*1024) throw Error('ZIP entry too large: '+name); if(method!==0&&method!==8) throw Error('Unsupported compression method for '+name); if(seen.has(name)) throw Error('Duplicate ZIP path: '+name); seen.add(name); totalUncompressed+=uncomp; if(totalUncompressed>50*1024*1024) throw Error('Adapter package expands beyond the 50 MB limit.'); files.push({name,method,compSize,uncomp,localOffset}); pos+=46+nameLen+extraLen+commentLen;}
 const out=[]; for(const f of files){if(f.name.endsWith('/')) continue; const lp=f.localOffset; if(view.getUint32(lp,true)!==0x04034b50) throw Error('Invalid ZIP local header.'); const nl=view.getUint16(lp+26,true), el=view.getUint16(lp+28,true); const start=lp+30+nl+el, compressed=buf.slice(start,start+f.compSize); let raw; if(f.method===0) raw=compressed; else {const ds=new DecompressionStream('deflate-raw'); raw=new Uint8Array(await new Response(new Blob([compressed]).stream().pipeThrough(ds)).arrayBuffer());} if(raw.byteLength!==f.uncomp) throw Error('ZIP size validation failed for '+f.name); if(raw.byteLength>0&&raw[0]===0){} const isText=/\.(json|js|md|txt|css|html|svg)$/i.test(f.name); let binary=''; if(!isText){ for(let i=0;i<raw.length;i+=0x8000) binary+=String.fromCharCode(...raw.slice(i,i+0x8000)); binary=btoa(binary); } out.push({path:f.name,type:isText?'text':'binary',content:isText?new TextDecoder().decode(raw):binary});}
 const manifestFile=out.find(x=>x.path.split('/').pop()==='adapter.json'); if(!manifestFile) throw Error('adapter.json is required.'); let manifest; try{manifest=JSON.parse(manifestFile.content)}catch{throw Error('adapter.json is invalid JSON.')} if(!/^[a-z0-9][a-z0-9._-]{1,63}$/i.test(manifest.id||'')) throw Error('Invalid adapter id.'); if(!/^\d+\.\d+\.\d+([+-][0-9A-Za-z.-]+)?$/.test(String(manifest.version||''))) throw Error('Adapter version must use semver like 1.0.0.'); if(manifest.entry && !out.some(x=>x.path===manifest.entry)) throw Error('Manifest entry file is missing.'); if(manifest.entry && (manifest.entry.includes('..')||manifest.entry.startsWith('/')||manifest.entry.includes('\\'))) throw Error('Unsafe adapter entry path.'); return {id:manifest.id,manifest,enabled:true,installedAt:new Date().toISOString(),files:out,storagePath:`extensions/adapters/${manifest.id}/`};
}
